:"code_node_FLgate","type":"code-node","properties":{"language":"javascript","code":"","timeout":30000,"isValidator":true,"nodeName":"IA floor: switch and gate","name":"IA floor: switch and gate","script":{"type":"javascript","code":"// MIN-01 RF-03: a Reserved subtract may not take the bucket below the open Item Assembly holds on this row. The IA's own
// completion (transaction type IA) is exempt: it takes Reserved only up to its own holds.
const IA_FLOOR_ENABLED = false;
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const D = /^[0-9]{1,20}$/;
const cat = s([{{workflowparams:inventory_category}}][0]);
const tt = s([{{workflowparams:transaction_type}}][0]);
const trx = s([{{workflowparams:trx_no}}][0]);
const mat = s([{{workflowparams:material_id}}][0]);
const bin = s([{{workflowparams:location_id}}][0]);
const plant = s([{{workflowparams:plant_id}}][0]);
const org = s([{{workflowparams:organization_id}}][0]);
const batch = s([{{workflowparams:batch_id}}][0]);
const tenant = s([{{system:tenantId}}][0]);
// DEV tests: a direct call with trx_no MIN01-TEST... runs the check while the switch is OFF
const wanted = (IA_FLOOR_ENABLED || trx.indexOf("MIN01-TEST") === 0) && cat === "Reserved" && tt !== "IA";
const ok = D.test(mat) && D.test(bin) && D.test(plant) && /^[0-9]{1,19}$/.test(org) && D.test(tenant) && (batch === "" || D.test(batch));
if (wanted && !ok) console.log("IA floor skipped: ids are not digits", mat, bin, plant, org, batch);
return { on: wanted && ok ? "YES" : "NO", mat: mat, bin: bin, plant: plant, org: org, tenant: tenant,
  batchCond: batch ? "o.batch_id = " + batch : "o.batch_id IS NULL" };"},"response_json":[{"key":"wsldpopa","name":"on","title":"on","description":"","bsonType":"string","isExpand":false},{"key":"8idmmtgm","name":"mat","title":"mat","description":"","bsonType":"string","isExpand":false},{"key":"j6hn2ahx","name":"bin","title":"bin","description":"","bsonType":"string","isExpand":false},{"key":"jw4ddjj3","name":"plant","title":"plant","description":"","bsonType":"string","isExpand":false},{"key":"ego66vgl","name":"org","title":"org","description":"","bsonType":"string","isExpand":false},{"key":"10f13ciy","name":"tenant","title":"tenant","description":"","bsonType":"string","isExpand":false},{"key":"7ndexgt6","name":"batchCond","title":"batchCond","description":"","bsonType":"string","isExpand":false}]}},{"id":"if_FLon","type":"if","properties":{"isValidator":true,"nodeName":"IF the IA floor applies: read the IA holds on this row","name":"IF the IA floor applies: read the IA holds on this row","condition_type":"Expression","filter":{"list":[{"id":1795000000003,"parentId":1795000000004,"isTop":true,"prop":"","operator":"","valueType":"","value":"","type":"leaf","level":1}]},"expression":{"type":"javascript","code":"'{{node:code_node_FLgate.data.on}}' == 'YES'"},"endNodeId":"condition_end_if_FLon"}},{"id":"condition_end_if_FLon","type":"condition-end-node","properties":{"conditionRootNodeId":"if_FLon"}},{"id":"condition_or_item_true_if_FLon","type":"condition-or-node-item","data":{"title":"true"},"properties":{"sort":1}},{"id":"condition_or_item_false_if_FLon","type":"condition-or-node-item","data":{"title":"false"},"properties":{"sort":1000}},{"id":"sql_node_FLholds","type":"sql-node","properties":{"script":{"type":"sql","code":"SELECT CAST(o.item_uom AS CHAR) AS uom, SUM(o.open_qty) AS open_qty,
       GROUP_CONCAT(DISTINCT o.doc_no ORDER BY o.doc_no SEPARATOR ', ') AS docs
  FROM on_reserved_gd o
 WHERE o.tenant_id = '{{node:code_node_FLgate.data.tenant}}'
   AND o.is_deleted = 0
   AND o.doc_type = 'Item Assembly'
   AND o.status IN ('Allocated', 'Processing', 'Releasing')
   AND o.open_qty > 0
